1	//! Virtual, cross-platform reproducible path handling.
2	
3	use std::error;
4	use std::ffi::OsStr;
5	use std::fmt::{self, Debug, Formatter};
6	use std::num::NonZeroU16;
7	use std::ops::Deref;
8	use std::path::{self, Path, PathBuf};
9	use std::sync::{LazyLock, RwLock};
10	
11	use ecow::{EcoString, eco_format};
12	use rustc_hash::FxHashMap;
13	use serde::{Deserialize, Serialize};
14	
15	use crate::package::PackageSpec;
16	
17	/// A path in a specific virtual file system root.
18	///
19	/// This identifies a location in a project or package.
20	#[derive(Clone, Eq, PartialEq, Hash)]
21	pub struct RootedPath {
22	    root: VirtualRoot,
23	    vpath: VirtualPath,
24	}
25	
26	impl RootedPath {
27	    /// Create a rooted path from a root and a virtual path within the root.
28	    pub fn new(root: VirtualRoot, vpath: VirtualPath) -> Self {
29	        Self { root, vpath }
30	    }
31	
32	    /// Turns this path into a `FileId`.
33	    pub fn intern(self) -> FileId {
34	        FileId::new(self)
35	    }
36	
37	    /// The root this path resides in.
38	    pub fn root(&self) -> &VirtualRoot {
39	        &self.root
40	    }
41	
42	    /// The package the path resides in, if any.
43	    #[deprecated = "use `root` instead"]
44	    pub fn package(&self) -> Option<&PackageSpec> {
45	        match self.root() {
46	            VirtualRoot::Project => None,
47	            VirtualRoot::Package(package) => Some(package),
48	        }
49	    }
50	
51	    /// The absolute and normalized path to the file _within_ the project or
52	    /// package.
53	    pub fn vpath(&self) -> &VirtualPath {
54	        &self.vpath
55	    }
56	
57	    /// Maps the virtual path while retaining the root.
58	    pub fn map(&self, f: impl FnOnce(&VirtualPath) -> VirtualPath) -> Self {
59	        Self::new(self.root.clone(), f(&self.vpath))
60	    }
61	}
62	
63	impl Debug for RootedPath {
64	    fn fmt(&self, f: &mut Formatter) -> fmt::Result {
65	        let vpath = self.vpath();
66	        match self.root() {
67	            VirtualRoot::Project => Debug::fmt(vpath, f),
68	            VirtualRoot::Package(package) => write!(f, "{package:?}{vpath:?}"),
69	        }
70	    }
71	}
72	
73	/// The root of a virtual file system.
74	#[derive(Debug, Clone, Eq, PartialEq, Hash)]
75	pub enum VirtualRoot {
76	    /// The canonical root of the Typst project.
77	    ///
78	    /// This is what `TYPST_ROOT` defines.
79	    Project,
80	    /// A root in a package.
81	    Package(PackageSpec),
82	}
83	
84	/// The global interner for rooted paths.
85	static INTERNER: LazyLock<RwLock<Interner>> = LazyLock::new(|| {
86	    RwLock::new(Interner { to_id: FxHashMap::default(), from_id: Vec::new() })
87	});
88	
89	/// An interner for rooted paths.
90	struct Interner {
91	    to_id: FxHashMap<&'static RootedPath, FileId>,
92	    from_id: Vec<&'static RootedPath>,
93	}
94	
95	/// An interned version of [`RootedPath`].
96	///
97	/// This type is globally interned and thus cheap to copy, compare, and hash.
98	#[derive(Copy, Clone, Eq, PartialEq, Hash)]
99	pub struct FileId(NonZeroU16);
100	
101	impl FileId {
102	    /// Create a new interned file specification.
103	    ///
104	    /// This is the same as [`RootedPath::intern`].
105	    #[track_caller]
106	    pub fn new(path: RootedPath) -> Self {
107	        // Try to find an existing entry that we can reuse.
108	        //
109	        // We could check with just a read lock, but if the pair is not yet
110	        // present, we would then need to recheck after acquiring a write lock,
111	        // which is probably not worth it.
112	        let mut interner = INTERNER.write().unwrap();
113	        if let Some(&id) = interner.to_id.get(&path) {
114	            return id;
115	        }
116	
117	        // Create a new entry forever by leaking the pair. We can't leak more
118	        // than 2^16 pair (and typically will leak a lot less), so its not a
119	        // big deal.
120	        let num = u16::try_from(interner.from_id.len() + 1)
121	            .and_then(NonZeroU16::try_from)
122	            .expect("out of file ids");
123	
124	        let id = FileId(num);
125	        let leaked = Box::leak(Box::new(path));
126	        interner.to_id.insert(leaked, id);
127	        interner.from_id.push(leaked);
128	        id
129	    }
130	
131	    /// Create a new unique ("fake") file specification, which is not accessible
132	    /// by path.
133	    ///
134	    /// Caution: the ID returned by this method is the *only* identifier of the
135	    /// file, constructing a file ID with a path will *not* reuse the ID even if
136	    /// the path is the same. This method should only be used for generating
137	    /// "virtual" file ids such as content read from stdin.
138	    ///
139	    /// While the returned ID is not otherwise accessible, the provided root and
140	    /// path still matter as they define how paths within the identified file
141	    /// will resolve. For the example of content read from stdin, it will define
142	    /// how a relative path in the stdin content is resolved.
143	    ///
144	    /// ## Example
145	    /// To create a globally available [`FileId`], use [`std::sync::LazyLock`]
146	    /// and build a [`RootedPath`] using [`VirtualRoot::Project`] and a custom
147	    /// [`VirtualPath`].
148	    /// ```
149	    /// use std::sync::LazyLock;
150	    /// use typst_syntax::*;
151	    /// static STDIN_ID: LazyLock<FileId> = LazyLock::new(|| {
152	    ///     FileId::unique(RootedPath::new(
153	    ///         VirtualRoot::Project,
154	    ///         VirtualPath::new("<stdin>").unwrap(),
155	    ///     ))
156	    /// });
157	    /// ```
158	    #[track_caller]
159	    pub fn unique(path: RootedPath) -> Self {
160	        let mut interner = INTERNER.write().unwrap();
161	        let num = u16::try_from(interner.from_id.len() + 1)
162	            .and_then(NonZeroU16::try_from)
163	            .expect("out of file ids");
164	
165	        let id = FileId(num);
166	        let leaked = Box::leak(Box::new(path));
167	        interner.from_id.push(leaked);
168	        id
169	    }
170	
171	    /// Create a new interned file id for use in tests. This should not be used
172	    /// for normal code, instead consider [`Self::unique`].
173	    #[track_caller]
174	    pub fn new_for_test(test_name: &'static str) -> Self {
175	        let vpath = VirtualPath::new(test_name).unwrap();
176	        RootedPath::new(VirtualRoot::Project, vpath).intern()
177	    }
178	
179	    /// Construct from a raw number.
180	    ///
181	    /// Should only be used with numbers retrieved via
182	    /// [`into_raw`](Self::into_raw). Misuse may results in panics, but no
183	    /// unsafety.
184	    pub const fn from_raw(v: NonZeroU16) -> Self {
185	        Self(v)
186	    }
187	
188	    /// Extract the raw underlying number.
189	    pub const fn into_raw(self) -> NonZeroU16 {
190	        self.0
191	    }
192	
193	    /// Get the static, interned rooted path.
194	    pub fn get(&self) -> &'static RootedPath {
195	        INTERNER.read().unwrap().from_id[usize::from(self.0.get() - 1)]
196	    }
197	}
198	
199	impl Deref for FileId {
200	    type Target = RootedPath;
201	
202	    fn deref(&self) -> &Self::Target {
203	        self.get()
204	    }
205	}
206	
207	impl Debug for FileId {
208	    fn fmt(&self, f: &mut Formatter) -> fmt::Result {
209	        self.get().fmt(f)
210	    }
211	}
212	
213	/// A path in a virtual file system.
214	#[derive(Clone, Eq, PartialEq, Hash)]
215	pub struct VirtualPath(Segments);
216	
217	impl VirtualPath {
218	    /// Creates a new virtual path.
219	    pub fn new(path: impl AsRef<str>) -> Result<Self, PathError> {
220	        let segments = Segments::normalize(components(path.as_ref()))?;
221	        Ok(Self(segments))
222	    }
223	
224	    /// Creates a virtual path from a real path and a real root.
225	    ///
226	    /// Returns `None` if the file path is not contained in the root (i.e. if
227	    /// `root_path` is not a lexical prefix of `path`). No file system
228	    /// operations are performed.
229	    ///
230	    /// This is the single function that translates from a real path to a
231	    /// virtual path. Its counterpart is [`VirtualPath::realize`].
232	    pub fn virtualize(root_path: &Path, path: &Path) -> Result<Self, VirtualizeError> {
233	        let path = path.strip_prefix(root_path).map_err(|_| PathError::Escapes)?;
234	        let mut segments = Segments::new();
235	        for c in path.components() {
236	            let comp = match c {
237	                path::Component::RootDir => Component::Root,
238	                path::Component::CurDir => Component::Current,
239	                path::Component::ParentDir => Component::Parent,
240	                path::Component::Normal(s) => {
241	                    let string = s.to_str().ok_or(VirtualizeError::Utf8)?;
242	                    let segment = Segment::new(string)
243	                        .map_err(|s| VirtualizeError::Invalid(s.into()))?;
244	                    Component::Normal(segment)
245	                }
246	                path::Component::Prefix(_) => return Err(PathError::Escapes.into()),
247	            };
248	            segments.push_component(comp)?;
249	        }
250	        Ok(Self(segments))
251	    }
252	
253	    /// Turns the virtual path into an actual file system path (where the
254	    /// project or package resides). You need to provide the appropriate `root`
255	    /// path, relative to which this path will be resolved.
256	    ///
257	    /// This is the single function that translates from a virtual path to a
258	    /// real path. Its counterpart is [`VirtualPath::virtualize`].
259	    ///
260	    /// This function has platform-specific output and returns an error if the
261	    /// path contains platform-specific syntax that could lexically escape the
262	    /// `root`. Currently, no file system operations are performed, though this
263	    /// may change in the future.
264	    ///
265	    /// This can be used in the implementations of `World::source` and
266	    /// `World::file`.
267	    pub fn realize(&self, root: &Path) -> Result<PathBuf, RealizeError> {
268	        let mut out = root.to_path_buf();
269	        for s in self.0.iter() {
270	            out.push(s.realize()?);
271	        }
272	        Ok(out)
273	    }
274	
275	    /// Extracts the path with a leading slash.
276	    pub fn into_with_slash(self) -> EcoString {
277	        self.0.into_with_slash()
278	    }
279	
280	    /// Returns the path with a leading slash.
281	    pub fn get_with_slash(&self) -> &str {
282	        self.0.get_with_slash()
283	    }
284	
285	    /// Returns the path without a leading slash.
286	    pub fn get_without_slash(&self) -> &str {
287	        self.0.get_without_slash()
288	    }
289	
290	    /// Whether this is the path `/`.
291	    pub fn is_root(&self) -> bool {
292	        self.0.is_empty()
293	    }
