893	        assert_eq!(p4.get_with_slash(), "/");
894	        assert_eq!(p4.join(".."), Err(PathError::Escapes));
895	    }
896	
897	    #[test]
898	    fn test_relative_from() {
899	        let p1 = path("src/text/main.typ");
900	        assert_eq!(p1.relative_from(&path("/src/text")), "main.typ");
901	        assert_eq!(p1.relative_from(&path("/src/data")), "../text/main.typ");
902	        assert_eq!(p1.relative_from(&path("src/")), "text/main.typ");
903	        assert_eq!(p1.relative_from(&path("/")), "src/text/main.typ");
904	
905	        let p2 = path("src");
906	        assert_eq!(p2.relative_from(&path("src")), "");
907	        assert_eq!(p2.relative_from(&path("src/data")), "..");
908	    }
