1	//! Source file management.
2	
3	use std::fmt::{self, Debug, Formatter};
4	use std::ops::Range;
5	use std::sync::Arc;
6	
7	use typst_utils::LazyHash;
8	
9	use crate::lines::Lines;
10	use crate::reparser::reparse;
11	use crate::{FileId, LinkedNode, Span, SpanNumber, SubRange, SyntaxNode, parse};
12	
13	/// A Typst source file containing the full source text, a mapping from byte
14	/// indices to lines/columns, and the parsed syntax tree.
15	///
16	/// All line and column indices start at zero, just like byte indices. Only for
17	/// user-facing display, you should add 1 to them.
18	///
19	/// Values of this type are cheap to clone and hash.
20	#[derive(Clone, Hash)]
21	pub struct Source(Arc<LazyHash<SourceInner>>);
22	
23	/// The internal representation of a [`Source`].
24	#[derive(Clone, Hash)]
25	struct SourceInner {
26	    id: FileId,
27	    root: SyntaxNode,
28	    lines: Lines<String>,
29	}
30	
31	impl Source {
32	    /// Create a new source file. This parses the input text and assigns span
33	    /// numbers to the parsed tree.
34	    pub fn new(id: FileId, text: impl Into<String>) -> Self {
35	        let text: String = text.into();
36	        #[cfg(feature = "timing")]
37	        let _scope = typst_timing::TimingScope::new("create source");
38	        let mut root = parse(&text);
39	        root.numberize(id, Span::FULL).unwrap();
40	        Self(Arc::new(LazyHash::new(SourceInner { id, lines: Lines::new(text), root })))
41	    }
42	
43	    /// Create a new source file with an already created syntax tree.
44	    pub fn with_root(id: FileId, text: String, root: SyntaxNode) -> Self {
45	        Self(Arc::new(LazyHash::new(SourceInner { id, lines: Lines::new(text), root })))
46	    }
47	
48	    /// The root node of the file's untyped syntax tree.
49	    pub fn root(&self) -> &SyntaxNode {
50	        &self.0.root
51	    }
52	
53	    /// The id of the source file.
54	    pub fn id(&self) -> FileId {
55	        self.0.id
56	    }
57	
58	    /// The whole source as a string slice.
59	    pub fn text(&self) -> &str {
60	        self.0.lines.text()
61	    }
62	
63	    /// An acceleration structure for conversion of UTF-8, UTF-16 and
64	    /// line/column indices.
65	    pub fn lines(&self) -> &Lines<String> {
66	        &self.0.lines
67	    }
68	
69	    /// Fully replace the source text.
70	    ///
71	    /// This performs a naive (suffix/prefix-based) diff of the old and new text
72	    /// to produce the smallest single edit that transforms old into new and
73	    /// then calls [`edit`](Self::edit) with it.
74	    ///
75	    /// Returns the range in the new source that was ultimately reparsed.
76	    pub fn replace(&mut self, new: &str) -> Range<usize> {
77	        #[cfg(feature = "timing")]
78	        let _scope = typst_timing::TimingScope::new("replace source");
79	
80	        let Some((prefix, suffix)) = self.0.lines.replacement_range(new) else {
81	            return 0..0;
82	        };
83	
84	        let old = self.text();
85	        let replace = prefix..old.len() - suffix;
86	        let with = &new[prefix..new.len() - suffix];
87	        self.edit(replace, with)
88	    }
89	
90	    /// Edit the source file by replacing the given range.
91	    ///
92	    /// Returns the range in the new source that was ultimately reparsed.
93	    ///
94	    /// The method panics if the `replace` range is out of bounds.
95	    #[track_caller]
96	    pub fn edit(&mut self, replace: Range<usize>, with: &str) -> Range<usize> {
97	        let inner = &mut **Arc::make_mut(&mut self.0);
98	
99	        // Update the text and lines.
100	        inner.lines.edit(replace.clone(), with);
101	
102	        // Incrementally reparse the replaced range.
103	        reparse(&mut inner.root, inner.lines.text(), replace, with.len())
104	    }
105	
106	    /// Find the node with the given span.
107	    ///
108	    /// Returns `None` if the span does not point into this source file.
109	    pub fn find(&self, span: Span) -> Option<LinkedNode<'_>> {
110	        if span.id() != Some(self.id()) {
111	            return None;
112	        }
113	        LinkedNode::new(self.root()).find(span)
114	    }
115	
116	    /// Get the byte range for the given span number (and optional sub-range) in
117	    /// this file.
118	    ///
119	    /// The main way to get a [`SpanNumber`] is by unpacking a span with
120	    /// [`Span::get`], but it's likely easier to use `WorldExt::range` instead.
121	    pub fn range(
122	        &self,
123	        num: SpanNumber,
124	        sub_range: Option<SubRange>,
125	    ) -> Option<Range<usize>> {
126	        let overall = LinkedNode::new(self.root()).find_number(num)?.range();
127	        if let Some(sub_range) = sub_range {
128	            let range = sub_range.to_absolute(overall.start);
129	            assert!(range.end <= overall.end);
130	            Some(range)
131	        } else {
132	            Some(overall)
133	        }
134	    }
135	}
136	
137	impl Debug for Source {
138	    fn fmt(&self, f: &mut Formatter) -> fmt::Result {
139	        write!(f, "Source({:?})", self.id().vpath())
140	    }
141	}
142	
143	impl AsRef<str> for Source {
144	    fn as_ref(&self) -> &str {
145	        self.text()
146	    }
147	}
148	
149	#[cfg(test)]
150	mod test {
151	    use super::Source;
152	    use crate::{FileId, LinkedNode, Side, Span, SubRange};
153	
154	    #[test]
155	    fn test_source_sub_ranges() {
156	        let test_id = FileId::new_for_test("test_source_sub_ranges");
157	        let text = "= head <label>";
158	        let source = Source::new(test_id, text);
159	        let get = |span: Span, sub_range| {
160	            let num = crate::SpanNumber(span.number());
161	            &text[source.range(num, sub_range).unwrap()]
162	        };
163	        let head = LinkedNode::new(source.root()).leaf_at(2, Side::After).unwrap().span();
164	        assert_eq!(get(head, None), "head");
165	        assert_eq!(get(head, SubRange::new(1, 3)), "ea");
166	        assert_eq!(get(head, SubRange::new(0, 1)), "h");
167	        assert_eq!(get(head, SubRange::new(0, 4)), "head");
168	        assert_eq!(get(head, SubRange::new(3, 4)), "d");
169	        let root = source.root().span();
170	        assert_eq!(get(root, None), text);
171	        assert_eq!(get(root, SubRange::new(3, 10)), "ead <la");
172	        assert_eq!(get(root, SubRange::new(0, 10)), "= head <la");
173	        assert_eq!(get(root, SubRange::new(3, 14)), "ead <label>");
174	    }
175	}
