314	    /// Returns a modified path with an adjusted extension.
315	    ///
316	    /// # Panics
317	    /// Panics if the resulting path segment would be invalid, e.g. because the
318	    /// extension contains a forward or backslash.
319	    #[track_caller]
320	    pub fn with_extension(&self, ext: &str) -> Self {
321	        let Some(stem) = self.file_stem() else { return self.clone() };
322	        let buf = eco_format!("{stem}.{ext}");
323	        let segment = Segment::new(&buf).expect("extension is invalid");
324	
325	        let mut segments = self.0.clone();
326	        segments.pop();
327	        segments.push(segment);
328	        Self(segments)
329	    }
