331	    /// Returns the path with its final component removed.
332	    ///
333	    /// Returns `None` if the path is already at the root.
334	    pub fn parent(&self) -> Option<Self> {
335	        let mut segments = self.0.clone();
336	        if !segments.pop() {
337	            return None;
338	        }
339	        Some(Self(segments))
340	    }
341	
342	    /// Joins the given `path` to `self`.
343	    pub fn join(&self, path: &str) -> Result<Self, PathError> {
344	        let combined = self
345	            .0
346	            .iter()
347	            .map(|c| Ok(Component::Normal(c)))
348	            .chain(components(path));
349	        let segments = Segments::normalize(combined)?;
350	        Ok(Self(segments))
351	    }
352	
353	    /// Expresses this path as a relative path from the given base path.
354	    pub fn relative_from(&self, base: &Self) -> EcoString {
355	        // Adapted from rustc's `path_relative_from` function (MIT).
356	        // Copyright 2012-2015 The Rust Project Developers.
357	        // See NOTICE for full attribution.
358	        let mut ita = self.0.iter();
359	        let mut itb = base.0.iter();
360	        let mut buf: Vec<&str> = vec![];
361	        loop {
362	            match (ita.next(), itb.next()) {
363	                (None, None) => break,
364	                (Some(a), None) => {
365	                    buf.push(a.get());
366	                    buf.extend(ita.map(Segment::get));
367	                    break;
368	                }
369	                (None, Some(_)) => buf.push(".."),
370	                (Some(a), Some(b)) if buf.is_empty() && a == b => (),
371	                (Some(a), Some(_)) => {
372	                    buf.extend(std::iter::repeat_n("..", 1 + itb.count()));
373	                    buf.push(a.get());
374	                    buf.extend(ita.map(Segment::get));
375	                    break;
376	                }
377	            }
378	        }
379	        buf.join("/").into()
380	    }
381	}
