436	/// A component in a virtual path.
437	#[derive(Debug, Copy, Clone, Eq, PartialEq)]
438	enum Component<'a> {
439	    Root,
440	    Current,
441	    Parent,
442	    Normal(Segment<'a>),
443	}
444	
445	// Special symbols in virtual paths.
446	const SEPARATOR: char = '/';
447	const CURRENT: &str = ".";
448	const PARENT: &str = "..";
449	
450	/// Splits a user-supplied path into its constituent parts.
451	///
452	/// This only splits and recognizes special segments. It does not check the
453	/// validity of normal segments. This is done in [`Segments::push`].
454	fn components(path: &str) -> impl Iterator<Item = Result<Component<'_>, PathError>> {
455	    path.split(SEPARATOR).enumerate().map(|(i, s)| {
456	        match s {
457	            // A leading separator indicates an absolute path.
458	            "" if i == 0 && !path.is_empty() => Ok(Component::Root),
459	            // Consecutive separators have no effect.
460	            "" => Ok(Component::Current),
461	            CURRENT => Ok(Component::Current),
462	            PARENT => Ok(Component::Parent),
463	            other => match Segment::new(other) {
464	                Ok(segment) => Ok(Component::Normal(segment)),
465	                Err("\\") => Err(PathError::Backslash),
466	                Err(_) => unreachable!(),
467	            },
468	        }
469	    })
470	}
471	
472	/// A segment in a normalized path.
473	///
474	/// A segments is never empty, `.`, or `..` and it never contains back- or
475	/// forward slashes.
476	#[derive(Debug, Copy, Clone, Eq, PartialEq)]
477	struct Segment<'a>(&'a str);
478	
479	impl<'a> Segment<'a> {
480	    fn new(segment: &'a str) -> Result<Self, &'a str> {
481	        // These invariants are important to avoid the path from escaping the
482	        // root after being realized, in particular the `..` part.
483	        if matches!(segment, "" | CURRENT | PARENT) {
484	            return Err(segment);
485	        }
486	
487	        // Interior separators or backslashes are not allowed.
488	        if let Some(m) = segment.matches([SEPARATOR, '\\']).next() {
489	            return Err(m);
490	        }
491	
492	        Ok(Self(segment))
493	    }
494	
495	    fn new_unchecked(segment: &'a str) -> Self {
496	        debug_assert!(Self::new(segment).is_ok());
497	        Self(segment)
498	    }
499	
500	    fn get(self) -> &'a str {
501	        self.0
502	    }
503	
504	    fn split_dot(self) -> (Option<&'a str>, Option<&'a str>) {
505	        let mut iter = self.0.rsplitn(2, '.');
506	        let after = iter.next();
507	        let before = iter.next();
508	        if before == Some("") { (Some(self.0), None) } else { (before, after) }
509	    }
510	
511	    /// Ensures that this segment can be joined to an existing platform-specific
512	    /// path without lexically escaping the root formed by that path.
513	    ///
514	    /// Sanity-checked against <https://pkg.go.dev/path/filepath#IsLocal>.
515	    fn realize(self) -> Result<&'a OsStr, RealizeError> {
516	        // We ensure that this segment corresponds to exactly one platform-level
517	        // path component. Drive letters on Windows are rejected since they are
518	        // `Prefix` components.
519	        let mut iter = Path::new(self.get()).components();
520	        match (iter.next(), iter.next()) {
521	            // Exactly one normal component.
522	            (Some(path::Component::Normal(s)), None) => {
523	                // Forbid access to reserved files on Windows as they are
524	                // conceptually not part of any root.
525	                #[cfg(windows)]
526	                if is_windows_reserved(self.get()) {
527	                    return Err(RealizeError::Invalid(self.get().into()));
528	                }
529	                Ok(s)
530	            }
531	            // No or multiple components, starting with normal.
532	            (None | Some(path::Component::Normal(_)), _) => {
533	                Err(RealizeError::Invalid(self.get().into()))
534	            }
535	            // Non-normal component.
536	            (Some(other), _) => {
537	                Err(RealizeError::Invalid(other.as_os_str().to_string_lossy().into()))
538	            }
539	        }
540	    }
541	}
542	
543	/// Whether the give file name is reserved on Windows.
544	///
545	/// Follows <https://cs.opensource.google/go/go/+/refs/tags/go1.26.4:src/internal/filepathlite/path_windows.go;l=98>.
546	/// See also: <https://learn.microsoft.com/en-us/windows/win32/fileio/naming-a-file>
547	#[cfg(windows)]
548	fn is_windows_reserved(name: &str) -> bool {
549	    #[rustfmt::skip]
550	    fn is_reserved_base(basename: &str) -> bool {
551	        matches!(
552	            basename,
553	            "CON" | "PRN" | "AUX" | "NUL"
554	                | "COM0" | "COM1" | "COM2" | "COM3" | "COM4" | "COM5" | "COM6"
555	                | "COM7" | "COM8" | "COM9" | "COM¹" | "COM²" | "COM³"
556	                | "LPT0" | "LPT1" | "LPT2" | "LPT3" | "LPT4" | "LPT5" | "LPT6"
557	                | "LPT7" | "LPT8" | "LPT9" | "LPT¹" | "LPT²" | "LPT³"
558	                | "CONIN$" | "CONOUT$"
559	        )
560	    }
561	
562	    // Some Windows versions also allow arbitrary characters after a dot or
563	    // colon in device names (and trailing spaces before that suffix).
564	    let base = name.split(['.', ':']).next().unwrap_or(name).trim_end_matches(' ');
565	    base.len() <= 7 && is_reserved_base(&EcoString::from(base).to_ascii_uppercase())
566	}
