568	/// Stores a sequence of path segments as a string.
569	///
570	/// The underlying string always represents a normalized absolute path and is
571	/// guaranteed to start with a slash. Segments are never empty, `.`, or `..` and
572	/// they never contain back- or forward slashes.
573	#[derive(Clone, Eq, PartialEq, Hash)]
574	struct Segments(EcoString);
575	
576	impl Segments {
577	    fn new() -> Self {
578	        Self(EcoString::from(SEPARATOR))
579	    }
580	
581	    fn normalize<'a>(
582	        comps: impl IntoIterator<Item = Result<Component<'a>, PathError>>,
583	    ) -> Result<Segments, PathError> {
584	        let mut out = Segments::new();
585	        for component in comps {
586	            out.push_component(component?)?;
587	        }
588	        Ok(out)
589	    }
590	
591	    fn is_empty(&self) -> bool {
592	        self.0.len() == 1
593	    }
594	
595	    fn into_with_slash(self) -> EcoString {
596	        self.0
597	    }
598	
599	    fn get_with_slash(&self) -> &str {
600	        &self.0
601	    }
602	
603	    fn get_without_slash(&self) -> &str {
604	        self.0.strip_prefix(SEPARATOR).expect("path to start with slash")
605	    }
606	
607	    fn clear(&mut self) {
608	        self.0.truncate(1);
609	    }
610	
611	    fn push_component(&mut self, component: Component) -> Result<(), PathError> {
612	        match component {
613	            // Root component resets the path.
614	            Component::Root => self.clear(),
615	            // Current component has no effect.
616	            Component::Current => {}
617	            // Parent component removes the last segment. If there is no
618	            // segment, this indicates that the path would escape the root.
619	            // In this case, we return an error.
620	            Component::Parent => {
621	                if !self.pop() {
622	                    return Err(PathError::Escapes);
623	                }
624	            }
625	            Component::Normal(segment) => self.push(segment),
626	        }
627	        Ok(())
628	    }
629	
630	    fn push(&mut self, segment: Segment) {
631	        if !self.is_empty() {
632	            self.0.push(SEPARATOR);
633	        }
634	        self.0.push_str(segment.0);
635	    }
636	
637	    fn pop(&mut self) -> bool {
638	        if self.is_empty() {
639	            return false;
640	        }
641	        let i = self.0.rfind(SEPARATOR).expect("to contain a slash");
642	        self.0.truncate(std::cmp::max(1, i));
643	        true
644	    }
645	
646	    fn last(&self) -> Option<Segment<'_>> {
647	        self.iter().next_back()
648	    }
649	
650	    fn iter(&self) -> impl DoubleEndedIterator<Item = Segment<'_>> {
651	        let mut iter = self.0[1..].split(SEPARATOR);
652	        if self.is_empty() {
653	            iter.next();
654	        }
655	        iter.map(Segment::new_unchecked)
656	    }
657	}
