214	/// The span of a diagnostic message. Either from a Typst source file or from a
215	/// loaded external file.
216	///
217	/// Typst source spans may additionally contain a sub-range targeting just part
218	/// of the overall range of the span.
219	///
220	/// When storing an external file range, the maximum value of the start/end is
221	/// `2^46-1`, larger values are saturated.
222	///
223	/// This type is stored compactly in 16 bytes and null-optimized, but can be
224	/// expanded for easier usage as the [`DiagSpanKind`] enum via [`Self::get()`].
225	#[derive(Clone, Copy, Eq, PartialEq, Hash)]
226	pub struct DiagSpan {
227	    span: Span,
228	    extra: u64,
229	}
230	
231	/// The possible kinds of a diagnostic span.
232	#[derive(Debug)]
233	pub enum DiagSpanKind {
234	    /// A span that does not point into any file.
235	    Detached,
236	    /// A numbered span with an optional sub-range.
237	    Number { id: FileId, num: SpanNumber, sub_range: Option<SubRange> },
238	    /// A raw byte range in a file.
239	    Range { id: FileId, range: Range<usize> },
240	}
241	
242	impl DiagSpan {
243	    /// The detached diagnostic span that does not point into any file.
244	    pub const fn detached() -> Self {
245	        Self { span: Span::DETACHED, extra: 0 }
246	    }
247	
248	    /// Create a new diagnostic span from an external file's byte range instead
249	    /// of an internal span.
250	    ///
251	    /// If either of the range's parts exceeds the maximum value of `2^46-1`, it
252	    /// will be saturated.
253	    pub fn from_range(id: FileId, range: Range<usize>) -> Self {
254	        let start = saturate(range.start, Span::EXTERNAL_VALUE_MAX);
255	        let end = saturate(range.end, Span::EXTERNAL_VALUE_MAX);
256	        Self {
257	            span: Span::pack(id, Span::EXTERNAL_BASE + start),
258	            extra: end,
259	        }
260	    }
261	
262	    /// Create a new diagnostic span from a source span and optional sub-range.
263	    ///
264	    /// The preferred interface for converting a [`Span`] into [`DiagSpan`] is
265	    /// using `span.into()`, which calls this with `sub_range: None`.
266	    pub fn from_span(span: Span, sub_range: Option<SubRange>) -> Self {
267	        let extra = sub_range.map_or(0, |SubRange { start, end }| {
268	            ((start as u64) << 32) | (end.get() as u64)
269	        });
270	        Self { span, extra }
271	    }
272	
273	    /// Whether the diagnostic span is detached.
274	    pub const fn is_detached(self) -> bool {
275	        self.span.0.get() == Span::DETACHED.0.get()
276	    }
277	
278	    /// The id of the file the span points into.
279	    ///
280	    /// Returns `None` if the span is detached.
281	    pub fn id(self) -> Option<FileId> {
282	        self.span.id()
283	    }
284	
285	    /// Return `other` if `self` is detached and `self` otherwise.
286	    pub fn or(self, other: Self) -> Self {
287	        if self.is_detached() { other } else { self }
288	    }
289	
290	    /// Unpack the diagnostic span into the variants of a [`DiagSpanKind`] for
291	    /// easier use.
292	    ///
293	    /// To access a range, you may want to use `WorldExt::range` instead.
294	    pub fn get(self) -> DiagSpanKind {
295	        let DiagSpan { span, extra } = self;
296	        match span.get() {
297	            SpanKind::Detached => DiagSpanKind::Detached,
298	            SpanKind::Number { id, num } => {
299	                if let Some(start) = num.0.checked_sub(Span::EXTERNAL_BASE) {
300	                    // This `checked_sub` must come after the internal range
301	                    // check from `span.get()`.
302	                    let start = start as usize;
303	                    let end = extra as usize;
304	                    DiagSpanKind::Range { id, range: start..end }
305	                } else {
306	                    let sub_range = {
307	                        let start = (extra >> 32) as u32;
308	                        let end = NonZeroU32::new(extra as u32); // `as` truncates
309	                        end.map(|end| SubRange { start, end })
310	                    };
311	                    DiagSpanKind::Number { id, num, sub_range }
312	                }
313	            }
314	            SpanKind::Range { id, range } => {
315	                if let Some(end) = NonZeroU32::new(extra as u32) {
316	                    let start = (extra >> 32) as u32;
317	                    let sub_range = SubRange { start, end };
318	                    let range = sub_range.to_absolute(range.start);
319	                    DiagSpanKind::Range { id, range }
320	                } else {
321	                    DiagSpanKind::Range { id, range }
322	                }
323	            }
324	        }
325	    }
326	}
