347	/// A non-empty range targeting a smaller part of a spanned section of text.
348	#[derive(Debug, Copy, Clone, Eq, PartialEq, Hash)]
349	pub struct SubRange {
350	    start: u32,
351	    end: NonZeroU32,
352	}
353	
354	impl SubRange {
355	    /// Create a new sub-range. The given start and end must create a non-empty
356	    /// range.
357	    ///
358	    /// If start or end are above a `2^32-1`, they will be saturated.
359	    pub fn new(start: usize, end: usize) -> Option<Self> {
360	        if start < end {
361	            Some(Self {
362	                start: to_u32_saturated(start),
363	                // (0 <= start) && (start < end) --> (end != 0)
364	                end: NonZeroU32::new(to_u32_saturated(end)).unwrap(),
365	            })
366	        } else {
367	            None
368	        }
369	    }
370	
371	    /// Convert to a normal range relative to the spanned range.
372	    pub fn to_relative(self) -> Range<usize> {
373	        Range {
374	            start: self.start as usize,
375	            end: self.end.get() as usize,
376	        }
377	    }
378	
379	    /// Convert to a normal range at an offset.
380	    pub fn to_absolute(self, offset: usize) -> Range<usize> {
381	        Range {
382	            start: self.start as usize + offset,
383	            end: self.end.get() as usize + offset,
384	        }
385	    }
386	}
