489	#[derive(Hash)]
490	pub struct RangeMapper {
491	    vec: Vec<Mapping>,
492	    total: usize,
493	}
494	
495	/// A mapping from an old index to a new one, guarantees that `old <= new`.
496	#[derive(Hash, Clone, Copy)]
497	struct Mapping {
498	    old: usize,
499	    new: usize,
500	}
501	
502	impl RangeMapper {
503	    /// Creates a new range mapper.
504	    ///
505	    /// The iterator should returns ranges in the original text that will be
506	    /// consecutively concatenated to produce the derived text.
507	    ///
508	    /// Segments should be in order. (The start of a later range must not
509	    /// precede the end of an earlier range.)
510	    ///
511	    /// Note that this representation implies that ranges can only ever increase
512	    /// in their start position and length when mapped.
513	    pub fn new(
514	        segments: impl IntoIterator<Item = Range<usize>>,
515	    ) -> Result<Self, EcoString> {
516	        let mut map = Mapping { old: 0, new: 0 };
517	        let vec = segments
518	            .into_iter()
519	            .map(|Range { start, end }| {
520	                if start > end || map.new > start {
521	                    return Err(eco_format!("invalid mapper segment: ({start}, {end})"));
522	                }
523	                map.new = start;
524	                let segment_map = map;
525	                map.old += end - start;
526	                Ok(segment_map)
527	            })
528	            .collect::<Result<Vec<Mapping>, EcoString>>()?;
529	
530	        if vec.is_empty() {
531	            Ok(Self { vec: vec![map], total: 0 })
532	        } else {
533	            Ok(Self { vec, total: map.old })
534	        }
535	    }
536	
537	    /// The total length of the original text.
538	    pub(crate) fn total_len(&self) -> usize {
539	        self.total
540	    }
541	
542	    /// Maps a range in the derived text back to a range in the original text.
543	    /// If the range spans over multiple segments, the gap between the two
544	    /// segments will be included in the resulting range.
545	    ///
546	    /// Input ranges must have  `start <= end`, and the caller should have
547	    /// verified that `end <= self.total`.
548	    pub(crate) fn map(&self, range: Range<usize>) -> Range<usize> {
549	        debug_assert!(range.start <= range.end);
550	        if range.end == 0 {
551	            // Handles the panic case of `map_end`.
552	            let offset = self.vec[0].new;
553	            offset..offset
554	        } else if range.start == range.end {
555	            // If start/end are at a boundary, map them to the first position,
556	            // not the second.
557	            let offset = self.map_end(range.start);
558	            offset..offset
559	        } else {
560	            // We now know that `start < end`, so the values from `map_start`
561	            // and `map_end` must be non-overlapping.
562	            let start = self.map_start(range.start);
563	            let end = self.map_end(range.end);
564	            start..end
565	        }
566	    }
567	
568	    /// Map a relative sub-range at an offset to a new sub-range. If the
569	    /// sub-range spans over multiple segments, the gap between them will be
570	    /// included in the new sub-range.
571	    pub(crate) fn map_sub_range(&self, offset: usize, sub_range: SubRange) -> SubRange {
572	        let range = sub_range.to_absolute(offset);
573	        let new_offset = self.map_start(offset);
574	        let start = self.map_start(range.start);
575	        let end = self.map_end(range.end); // sub-ranges have `start < end`.
576	        SubRange::new(start - new_offset, end - new_offset).unwrap()
577	    }
578	
579	    /// Map a single offset, preferring the second index if at a boundary.
580	    fn map_start(&self, offset: usize) -> usize {
581	        let idx = self.vec.partition_point(|&Mapping { old, new: _ }| old <= offset);
582	        // Subtracting by 1 is valid: vec is non-empty, index 0 has `old == 0`,
583	        // and `partition_point` returns the index of the first item to fail the
584	        // predicate (or the length), which is not index 0, since `0 <= usize`
585	        // is true for all usize.
586	        let Mapping { old, new } = &self.vec[idx - 1];
587	        new + (offset - old)
588	    }
589	
590	    /// Map a single offset, preferring the first index if at a boundary.
591	    ///
592	    /// This will panic if `offset` is 0.
593	    fn map_end(&self, offset: usize) -> usize {
594	        debug_assert_ne!(offset, 0);
595	        let idx = self.vec.partition_point(|&Mapping { old, new: _ }| old < offset);
596	        // Unlike `map_start`, this can yield index 0 when `offset == 0`, making
597	        // `idx - 1` potentially panicking.
598	        let Mapping { old, new } = &self.vec[idx - 1];
599	        new + (offset - old)
600	    }
601	}
